SELECT amount_bucket, txn_type_values, avg_amount FROM (SELECT CASE WHEN amount >= 3200 THEN 'high' WHEN amount >= 900 THEN 'mid' ELSE 'low' END AS amount_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(txn_type))) AS txn_type_values, ROUND(AVG(amount), 2) AS avg_amount FROM transactions GROUP BY CASE WHEN amount >= 3200 THEN 'high' WHEN amount >= 900 THEN 'mid' ELSE 'low' END) AS agg WHERE avg_amount > 53 ORDER BY amount_bucket, avg_amount DESC LIMIT 10;
